def test_manifest_shape_errors_are_rejected(tmp_path: Path) -> None:
    """Both the JSON root and the export grouping must be objects."""
    path = tmp_path / "manifest.json"
    path.write_text("[]", encoding="utf-8")
    with pytest.raises(ValueError, match="manifest must be an object"):
        load_manifest(path)
    with pytest.raises(ValueError, match="api_groups must be an object"):
        validate_manifest({"api_groups": []})


def test_entry_fallbacks_cover_undocumented_objects() -> None:
    """Generated entries distinguish aliases from other undocumented values."""

    class Undocumented:
        pass

    Undocumented.__doc__ = None
    module = SimpleNamespace(Path=Undocumented(), singleton=Undocumented())
    assert "type alias" in generate_docs._entry(module, "Path", {})
    assert "singleton" in generate_docs._entry(module, "singleton", {})
    assert generate_docs._signature(object()) == ""


def test_class_entries_include_public_members_once_in_definition_order() -> None:
    """Methods, classmethods, and properties are class reference entries."""

    class Example:
        """Example class."""

        def method(self, value: int) -> int:
            """Return one value."""
            return value

        @classmethod
        def create(cls) -> Example:
            """Create an example."""
            return cls()

        @property
        def ready(self) -> bool:
            """Report readiness."""
            return True

        def _private(self) -> None:
            """Stay out of the public reference."""

    rendered = generate_docs._entry(SimpleNamespace(Example=Example), "Example", {})
    headings = [
        rendered.index("#### `Example.method`"),
        rendered.index("#### `Example.create`"),
        rendered.index("#### `Example.ready`"),
    ]
    assert headings == sorted(headings)
    assert rendered.count("#### `Example.method`") == 1
    assert rendered.count("#### `Example.create`") == 1
    assert rendered.count("#### `Example.ready`") == 1
    assert "Example._private" not in rendered


def test_class_entries_render_static_methods_and_omit_unreadable_members() -> None:
    """CHARACTERIZATION: static methods render; write-only and undocumented members do not."""

    class Example:
        """Example class."""

        @staticmethod
        def helper(value: int) -> int:
            """Return one value."""
            return value

        def undocumented(self) -> None:
            pass

        def _store(self, value: int) -> None:
            """Store a value on the example."""

        write_only = property(None, _store)

    rendered = generate_docs._entry(SimpleNamespace(Example=Example), "Example", {})
    assert "#### `Example.helper`" in rendered
    assert "Static method." in rendered
    assert "Example.undocumented" not in rendered
    assert "Example.write_only" not in rendered


@pytest.mark.parametrize(
    ("stdout", "stderr", "message"),
    [("", "boom", "wrote to stderr"), ("not JSON\n", "", "line 1 is not JSON")],
)
def test_cli_stepping_example_failures_are_rejected(
    monkeypatch: pytest.MonkeyPatch, stdout: str, stderr: str, message: str
) -> None:
    """CHARACTERIZATION: the stepping example must be silent on stderr and JSON on stdout."""
    monkeypatch.setattr(
        subprocess,
        "run",
        lambda *args, **kwargs: SimpleNamespace(stdout=stdout, stderr=stderr),
    )
    with pytest.raises(ValueError, match=message):
        generate_docs.cli_bytes()


def test_missing_generated_directive_is_rejected() -> None:
    with pytest.raises(ValueError, match="expected one 'copy-example' directive"):
        generate_docs._replace_directive("plain text", "copy-example", "body")


def test_gate_step_without_a_gloss_is_refused(monkeypatch: pytest.MonkeyPatch) -> None:
    """A step added to `gate` stops the render, naming the step and the fix.

    The contributor-facing gate list takes its order and membership from the
    makefile; only the one-line gloss is written by hand. Adding a step to
    `gate` and forgetting the gloss is therefore the one way to reach this
    render with nothing to say about a step, and the person who did it is
    holding a makefile, not this module.
    """
    monkeypatch.setattr(generate_docs, "gate_steps", lambda: ("lint", "unglossed"))
    with pytest.raises(ValueError, match="gate step 'unglossed' has no gloss"):
        generate_docs.contributing_bytes()


