def test_cli_failures_are_rejected(monkeypatch: pytest.MonkeyPatch) -> None:
    bad = SimpleNamespace(returncode=1, stderr="bad", stdout="")
    monkeypatch.setattr(subprocess, "run", lambda *a, **k: bad)
    with pytest.raises(ValueError, match="CLI contract failed"):
        generate_docs.check_cli()

    calls = iter(
        [
            SimpleNamespace(returncode=0, stderr="", stdout=""),
            SimpleNamespace(returncode=0, stderr="", stdout=""),
            SimpleNamespace(returncode=0, stderr="", stdout='{"version":"bad"}'),
        ]
    )
    monkeypatch.setattr(subprocess, "run", lambda *a, **k: next(calls))
    with pytest.raises(ValueError, match="version JSON"):
        generate_docs.check_cli()


